 private function reject(callable $call,string $message=''):void{try{$call();self::fail('Expected rejection');}catch(\DomainException|\ShopInventoryException $e){self::assertNotSame('',$e->getMessage());if($message!=='')self::assertStringContainsString($message,$e->getMessage());}}
