  $this->reject(fn()=>\shopReturnDispose($this->pdo,(int)$r['id'],(int)$r['revision'],'unblock',date('Y-m-d'),8,'Incorrect stock permission.',true,'bad-disposition'),'oprávnění');
  $r=\shopReturnDispose($this->pdo,(int)$r['id'],(int)$r['revision'],'unblock',date('Y-m-d'),9,'Inspection confirms saleability.',true,'unblock-case-one');self::assertSame(1,$this->b()['available_quantity']);self::assertSame('saleable',$r['disposition']);
  self::assertSame('M',$this->pdo->query('SELECT sku_snapshot FROM shop_order_items')->fetchColumn());self::assertSame(0,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());
 }
