 public function testFinanceRoleAndClosureDoNotTrustOperatorDeclarations():void{$r=$this->receive($this->open());$this->reject(fn()=>\shopReturnClose($this->pdo,(int)$r['id'],(int)$r['revision'],8,'Try close before inspection.',true,'early-closure'));$this->reject(fn()=>\shopReturnFinancialResolution($this->pdo,(int)$r['id'],(int)$r['revision'],'no_adjustment',0,0,'Incorrect finance privilege.',8,'Attempt financial confirmation.',true,'operator-finance'),'oprávnění');}
 public function testExchangeReservesLastDifferentVariantKeepsOriginalAndIssuesNoFakeSale():void {
