 public function testExchangeCancellationReleasesReservedStock():void{$r=$this->open('voluntary_exchange');$r=\shopReturnExchangeReserve($this->pdo,(int)$r['id'],(int)$r['revision'],2,5000,8,'Agreed equal value exchange.',true,'exchange-to-cancel');$r=\shopReturnCancel($this->pdo,(int)$r['id'],(int)$r['revision'],8,'Customer cancelled exchange.',true,'exchange-cancelled');self::assertSame('cancelled',$r['state']);self::assertSame(1,$this->b(2)['available_quantity']);}
 public function testRolesRevocationDatesAndNoConfirmationAreRejected():void{$input=$this->input();$this->reject(fn()=>\shopReturnOpen($this->pdo,$input,11,'Coach cannot manage returns.',true));$this->reject(fn()=>\shopReturnOpen($this->pdo,$input,8,'No confirmation supplied.',false));$this->reject(fn()=>\shopReturnOpen($this->pdo,['occurred_on'=>'2026-01-01']+$input,8,'Date before physical issue.',true),'předcházet');$r=$this->open();$this->pdo->exec("DELETE FROM staff_user_positions WHERE trainer_id=8");$this->reject(fn()=>$this->receive($r),'oprávnění');}
 private function document(string $type,int $source,int $amount,string $line,?int $original=null):int {
  $snapshot=json_encode(['lines'=>[['line_key'=>$line,'quantity'=>1,'amount_minor'=>$amount]]],JSON_THROW_ON_ERROR);$s=$this->pdo->prepare('INSERT INTO accounting_documents(kind,source_type,source_id,original_document_id,idempotency_key,status,snapshot_json,snapshot_sha256,total_minor,currency,effective_on,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$original?'correction':'invoice',$type,$source,$original,'doc-'.++$this->seq,'issued',$snapshot,hash('sha256',$snapshot),$amount,'CZK',date('Y-m-d'),10]);return(int)$this->pdo->lastInsertId();
 }
 private function money(int $amount,string $case='shop_order',int $source=1):int {
  require_once dirname(__DIR__,2).'/includes/accounting_ledger.php';require_once dirname(__DIR__,2).'/includes/accounting_adjustments.php';
  if(!(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_accounts')->fetchColumn())\accountingLedgerCreateAccount($this->pdo,['code'=>'LOCALHOST','name'=>'LOCALHOST NEPLATIT','kind'=>'bank','currency'=>'CZK','opened_on'=>date('Y-m-d'),'opening_minor'=>0,'evidence'=>'Synthetic bank opening'],10,'LOCALHOST NEPLATIT opening.',true);
  $key='income-'.++$this->seq;$m=\accountingLedgerRecord($this->pdo,['account_id'=>1,'kind'=>'income','amount_minor'=>$amount,'currency'=>'CZK','effective_on'=>date('Y-m-d'),'source_context'=>'LOCALHOST','source_reference'=>$key,'request_key'=>$key,'case_type'=>$case,'case_id'=>$source,'evidence'=>'Synthetic actual income'],10,'LOCALHOST NEPLATIT actual receipt.',true);return(int)$m['id'];
 }
 private function decision(int $money,int $original,int $correction,int $amount):int{$d=\accountingRefundDecide($this->pdo,['original_movement_id'=>$money,'original_document_id'=>$original,'correction_document_id'=>$correction,'amount_minor'=>$amount,'decided_on'=>date('Y-m-d'),'request_key'=>'decision-'.++$this->seq],10,'LOCALHOST NEPLATIT refund decision.',true);return(int)$d['id'];}
 private function payout(int $decision,int $amount):void{\accountingRefundPay($this->pdo,$decision,['account_id'=>1,'amount_minor'=>$amount,'effective_on'=>date('Y-m-d'),'source_reference'=>'refund-'.++$this->seq,'evidence'=>'Synthetic actual bank outflow','request_key'=>'payout-'.++$this->seq],10,'LOCALHOST NEPLATIT actual refund.',true);}
 public function testPaidPartialReturnClosesOnlyAfterLinkedActualRefundAndNoMoneyCreatedByStock():void {
  $r=$this->receive($this->open());$r=\shopReturnDispose($this->pdo,(int)$r['id'],(int)$r['revision'],'unblock',date('Y-m-d'),9,'Saleable after physical inspection.',true,'financial-return-unblock');
  $original=$this->document('order',1,10000,'item:1');$correction=$this->document('order',1,-5000,'item:1',$original);$income=$this->money(10000);$decision=$this->decision($income,$original,$correction,5000);
  $r=\shopReturnFinancialResolution($this->pdo,(int)$r['id'],(int)$r['revision'],'adjustment',$correction,$decision,'Original sale and return reconciled.',10,'Verify canonical refund documents.',true,'financial-return-resolution');
  self::assertSame(1,(int)$this->pdo->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());$this->reject(fn()=>\shopReturnClose($this->pdo,(int)$r['id'],(int)$r['revision'],8,'Wait actual repayment first.',true,'unpaid-return-close'),'vyplacena');
  $this->payout($decision,2000);$this->reject(fn()=>\shopReturnClose($this->pdo,(int)$r['id'],(int)$r['revision'],8,'Still partial repayment only.',true,'partial-return-close'),'vyplacena');$this->payout($decision,3000);
  $r=\shopReturnClose($this->pdo,(int)$r['id'],(int)$r['revision'],8,'Actual full refund verified.',true,'paid-return-close');self::assertSame('closed',$r['state']);self::assertSame(1,$this->b()['available_quantity']);self::assertSame(5000,\accountingLedgerBalance($this->pdo,1,date('Y-m-d'))['closing_minor']);
 }
