 public function testReplacementReturnTraversesSnapshotsAndAcceptsSplitOriginalPlusDeltaCorrections():void {
  $e=$this->open('voluntary_exchange');$e=\shopReturnExchangeReserve($this->pdo,(int)$e['id'],(int)$e['revision'],2,6000,8,'Customer agrees higher replacement price.',true,'chain-exchange-reserve');$e=$this->receive($e);
  $income=$this->money(10000);$deltaIncome=$this->money(1000,'shop_return',(int)$e['id']);\accountingLedgerAllocate($this->pdo,$deltaIncome,'shop_return',(int)$e['id'],1000,'delta-payment-allocation',10,'Allocate exact replacement difference.',true);
  $e=\shopReturnFinancialResolution($this->pdo,(int)$e['id'],(int)$e['revision'],'adjustment',0,0,'Supplemental obligation paid separately.',10,'Verify supplemental exchange price.',true,'chain-exchange-finance');$e=\shopReturnExchangeIssue($this->pdo,(int)$e['id'],(int)$e['revision'],'LOCALHOST parent',date('Y-m-d'),8,'Actual replacement handed over.',true,'chain-exchange-issue');
  $input=['issue_movement_id'=>(int)$e['exchange_issue_movement_id']]+$this->input();$r=\shopReturnOpen($this->pdo,$input,8,'Return the actual replacement.',true);self::assertSame(6000,(int)$r['original_amount_minor']);self::assertSame(2,(int)$r['variant_id']);self::assertSame('L',json_decode($r['original_snapshot_json'],true)['sku']);
  $r=$this->receive($r);$r=\shopReturnDispose($this->pdo,(int)$r['id'],(int)$r['revision'],'unblock',date('Y-m-d'),9,'Replacement inspected as saleable.',true,'chain-return-unblock');
  $original=$this->document('order',1,10000,'item:1');$c1=$this->document('order',1,-5000,'item:1',$original);$deltaDoc=$this->document('shop_return',(int)$e['id'],1000,'exchange:'.$e['id']);$c2=$this->document('shop_return',(int)$e['id'],-1000,'exchange:'.$e['id'],$deltaDoc);
  $d1=$this->decision($income,$original,$c1,5000);$q=$this->pdo->query("SELECT id FROM accounting_allocations WHERE case_type='shop_return'");$allocationId=(int)$q->fetchColumn();\accountingLedgerAllocate($this->pdo,$deltaIncome,'shop_return',(int)$e['id'],-1000,'delta-release-return',10,'Release refunded replacement difference.',true,$allocationId);$d2=$this->decision($deltaIncome,$deltaDoc,$c2,1000);
  $r=\shopReturnAttachCorrection($this->pdo,(int)$r['id'],(int)$r['revision'],$c1,$d1,5000,10,'Link returned original price portion.',true,'chain-link-first');$this->reject(fn()=>\shopReturnFinancialResolution($this->pdo,(int)$r['id'],(int)$r['revision'],'adjustment',0,0,'Missing replacement delta correction.',10,'Do not omit replacement difference.',true,'chain-incomplete'),'přesně');
  $r=\shopReturnAttachCorrection($this->pdo,(int)$r['id'],(int)$r['revision'],$c2,$d2,1000,10,'Link returned supplemental price.',true,'chain-link-second');$r=\shopReturnFinancialResolution($this->pdo,(int)$r['id'],(int)$r['revision'],'adjustment',0,0,'Both original and replacement corrections.',10,'All documented return price reconciles.',true,'chain-financial-complete');$this->payout($d1,5000);$this->payout($d2,1000);$r=\shopReturnClose($this->pdo,(int)$r['id'],(int)$r['revision'],8,'All chained physical and money steps done.',true,'chain-return-closed');self::assertSame('closed',$r['state']);self::assertSame(2,(int)$this->pdo->query('SELECT COUNT(*) FROM shop_return_finance_links')->fetchColumn());self::assertSame(1,$this->b(2)['available_quantity']);
 }

